export class Atmosphere{
 constructor(){this.enabled=false;this.context=null;}
 async toggle(){if(!this.context)this.init();this.enabled=!this.enabled;if(this.enabled)await this.context.resume();else await this.context.suspend();return this.enabled;}
 init(){const AC=window.AudioContext||window.webkitAudioContext;this.context=new AC();const c=this.context;this.master=c.createGain();this.master.gain.value=.11;this.master.connect(c.destination);const buffer=c.createBuffer(1,c.sampleRate*3,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1);const noise=c.createBufferSource();noise.buffer=buffer;noise.loop=true;const low=c.createBiquadFilter();low.type='lowpass';low.frequency.value=1300;const gain=c.createGain();gain.gain.value=.25;noise.connect(low);low.connect(gain);gain.connect(this.master);noise.start();for(const hz of [55,82.4,110.15]){const osc=c.createOscillator();osc.frequency.value=hz;const g=c.createGain();g.gain.value=.035;osc.connect(g);g.connect(this.master);osc.start();}}
 chime(kind='action'){if(!this.enabled||!this.context)return;const c=this.context,now=c.currentTime;[0,1,2].forEach(i=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=(kind==='rewind'?220:kind==='win'?440:330)*[1,1.25,1.5][i];g.gain.setValueAtTime(0,now+i*.11);g.gain.linearRampToValueAtTime(.15,now+i*.11+.03);g.gain.exponentialRampToValueAtTime(.001,now+i*.11+1.3);o.connect(g);g.connect(this.master);o.start(now+i*.11);o.stop(now+i*.11+1.4);});}
 suspend(){this.context?.suspend();}resume(){if(this.enabled)this.context?.resume();}
}
